from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Remove spaces from the input string
    balanced_groups = []  # Initialize an empty list to store the balanced groups
    stack = []  # Stack to track opening and closing parentheses

    for char in paren_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if stack and stack[-1] == '(':
                stack.pop()
                if len(stack) == 0:
                    balanced_groups.append('(' + paren_string[:paren_string.index(char) + 1] + ')')

    return balanced_groups

